arguments.command:
cd /workspace && echo "=== submission tree ===" && find submission -type f | sort && echo && echo "=== sizes ===" && python3 -c "
import os
tot=0;entries=0
for base,dirs,files in os.walk('/workspace/submission'):
    for n in dirs+files:
        entries+=1; p=os.path.join(base,n)
        if os.path.isfile(p): tot+=os.path.getsize(p)
print('entries:',entries,'/ 512   bytes:',tot,'/ 16777216')
" && echo && echo "=== public check ===" && python3 public_check.py submission
